'use client'

import { use } from 'react'
import Link from 'next/link'
import { useAnalysis } from '@/lib/queries'
import { ApiError } from '@/lib/api'
import { ResultsSkeleton } from '@/components/results/ResultsSkeleton'
import { ScoreCard } from '@/components/results/ScoreCard'
import { ProblemsSection } from '@/components/results/ProblemsSection'
import { RewriteSection } from '@/components/results/RewriteSection'
import { PremiumGate } from '@/components/results/PremiumGate'
import { LoadingSpinner } from '@/components/shared/LoadingSpinner'
import { ErrorMessage } from '@/components/shared/ErrorMessage'

export default function ResultsPage({
  params,
}: {
  params: Promise<{ id: string }>
}) {
  const { id } = use(params)
  const { data: analysis, isLoading, isError, error } = useAnalysis(id)

  // Initial loading skeleton
  if (isLoading && !analysis) {
    return (
      <main className="min-h-screen bg-slate-50 py-12 px-4">
        <div className="max-w-2xl mx-auto">
          <ResultsSkeleton />
        </div>
      </main>
    )
  }

  // Error states
  if (isError) {
    const is404 = error instanceof ApiError && error.status === 404

    return (
      <main className="min-h-screen bg-slate-50 py-12 px-4">
        <div className="max-w-2xl mx-auto">
          {is404 ? (
            <div className="bg-white rounded-xl border border-slate-200 p-8 text-center">
              <p className="text-slate-700 font-medium mb-2">Analysis not found</p>
              <p className="text-sm text-slate-500 mb-6">
                This analysis doesn&apos;t exist or you don&apos;t have access to it.
              </p>
              <Link
                href="/analyze"
                className="text-primary text-sm font-medium hover:underline"
              >
                ← Start a new analysis
              </Link>
            </div>
          ) : (
            <ErrorMessage message="Something went wrong loading your results. Please refresh the page." />
          )}
        </div>
      </main>
    )
  }

  if (!analysis) return null

  return (
    <main className="min-h-screen bg-slate-50 py-12 px-4">
      <div className="max-w-2xl mx-auto space-y-6">
        {/* Header */}
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Your profile analysis</h1>
          <p className="text-slate-500 mt-1 text-sm">
            <Link href="/analyze" className="text-primary hover:underline">
              ← Run another analysis
            </Link>
          </p>
        </div>

        {/* Score — always shown */}
        <ScoreCard score={analysis.score} />

        {/* Problems — always shown */}
        <ProblemsSection problems={analysis.problems} />

        {/* Status-dependent section */}
        {analysis.status === 'scored' && <PremiumGate />}

        {analysis.status === 'generating' && (
          <div className="bg-white rounded-xl border border-slate-200 p-8 flex justify-center">
            <LoadingSpinner label="Generating your rewrite…" />
          </div>
        )}

        {analysis.status === 'complete' && analysis.rewrite && (
          <RewriteSection rewrite={analysis.rewrite} />
        )}

        {analysis.status === 'failed' && (
          <ErrorMessage message="Rewrite generation failed. Please try again." />
        )}
      </div>
    </main>
  )
}
